use std::fs;
use std::path::PathBuf;

use anyhow::{bail, Context, Result};
use clap::Parser;
use tolmap::schema::{District, LandmarkRow, MapDocument, NodeRow, RoadRow, SymbolRow};
use ts_rs::{Config, TS};

#[derive(Debug, Parser)]
struct Args {
    #[arg(long)]
    check: bool,
    #[arg(long, default_value = "generated/MapDocument.ts")]
    output: PathBuf,
}

fn main() -> Result<()> {
    let args = Args::parse();
    let config = Config::default();
    let generated = format!(
        "// Generated by `cargo run --bin generate-types`; do not edit.\n\n{}\n\n{}\n\n{}\n\n{}\n\n{}\n\n{}\n",
        District::decl(&config),
        NodeRow::decl(&config),
        LandmarkRow::decl(&config),
        SymbolRow::decl(&config),
        RoadRow::decl(&config),
        MapDocument::decl(&config)
    );
    if args.check {
        let current = fs::read_to_string(&args.output)
            .with_context(|| format!("read {}", args.output.display()))?;
        if current != generated {
            bail!("{} is stale; regenerate it", args.output.display());
        }
    } else {
        if let Some(parent) = args.output.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(&args.output, generated)?;
    }
    Ok(())
}
